import React from 'react';
import { useInView } from 'react-intersection-observer';
import { FaGraduationCap, FaBriefcase, FaAward, FaCode } from 'react-icons/fa';

const Timeline = () => {
  const [ref, inView] = useInView({
    triggerOnce: true,
    threshold: 0.1,
  });

  const events = [
    {
      year: '2024',
      title: 'Data Analytics Projects',
      description: 'Completed 5+ major data analytics projects with real-world impact',
      icon: FaCode,
      color: 'from-purple-500 to-pink-500',
      achievements: ['10% cost reduction', '30% efficiency boost', '1.8M records processed']
    },
    {
      year: '2023',
      title: 'Data Analytics Intern',
      description: 'Data Analytics Internship at MedTourEasy',
      icon: FaBriefcase,
      color: 'from-blue-500 to-cyan-500',
      achievements: ['Power BI dashboards', 'MySQL optimization', 'Statistical analysis']
    },
    {
      year: '2022',
      title: 'B.Tech Computer Science',
      description: 'Graduated with CGPA 8.3/10',
      icon: FaGraduationCap,
      color: 'from-green-500 to-emerald-500',
      achievements: ['Specialization in Data Science', 'Research Projects', 'Academic Excellence']
    },
    {
      year: '2021',
      title: 'Certifications',
      description: 'Advanced certifications in SQL and Data Analytics',
      icon: FaAward,
      color: 'from-orange-500 to-red-500',
      achievements: ['SQL Expert Certification', 'Power BI Advanced', 'Python for Data Science']
    }
  ];

  return (
    <section className="py-20 bg-gradient-to-b from-gray-900 to-black">
      <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8">
        <div className="text-center mb-12">
          <h2 className="text-4xl md:text-5xl font-bold bg-gradient-to-r from-purple-500 to-pink-500 bg-clip-text text-transparent">
            Journey & Timeline
          </h2>
          <div className="w-24 h-1 bg-gradient-to-r from-purple-500 to-pink-500 mx-auto mt-4"></div>
          <p className="text-gray-400 mt-4">My professional journey so far</p>
        </div>

        <div ref={ref} className="relative">
          {/* Vertical Line */}
          <div className="absolute left-1/2 transform -translate-x-1/2 w-0.5 h-full bg-gradient-to-b from-purple-500 via-pink-500 to-purple-500 hidden md:block"></div>
          
          <div className="space-y-12">
            {events.map((event, idx) => (
              <div
                key={idx}
                className={`relative flex flex-col md:flex-row items-center ${
                  idx % 2 === 0 ? 'md:flex-row' : 'md:flex-row-reverse'
                } transform transition-all duration-700 ${
                  inView ? 'translate-x-0 opacity-100' : 'translate-x-20 opacity-0'
                }`}
                style={{ transitionDelay: `${idx * 200}ms` }}
              >
                {/* Timeline Dot */}
                <div className="absolute left-1/2 transform -translate-x-1/2 w-4 h-4 bg-purple-500 rounded-full hidden md:block z-10"></div>
                
                {/* Content */}
                <div className="md:w-1/2 p-6">
                  <div className="bg-gradient-to-br from-gray-800 to-gray-900 rounded-xl p-6 border border-gray-700 hover:border-purple-500 transition-all duration-300 transform hover:scale-105 hover:shadow-xl hover:shadow-purple-500/20">
                    <div className="flex items-center gap-3 mb-3">
                      <div className={`bg-gradient-to-r ${event.color} rounded-lg p-2`}>
                        <event.icon className="text-white text-xl" />
                      </div>
                      <span className="text-purple-500 font-bold text-xl">{event.year}</span>
                    </div>
                    <h3 className="text-xl font-bold text-white mb-2">{event.title}</h3>
                    <p className="text-gray-400 mb-3">{event.description}</p>
                    <ul className="space-y-1">
                      {event.achievements.map((achievement, i) => (
                        <li key={i} className="text-sm text-gray-500 flex items-center gap-2">
                          <span className="w-1.5 h-1.5 bg-purple-500 rounded-full"></span>
                          {achievement}
                        </li>
                      ))}
                    </ul>
                  </div>
                </div>
              </div>
            ))}
          </div>
        </div>
      </div>
    </section>
  );
};

export default Timeline;
